function zoomRunSettings(settings, now) {
  if (
    !settings ||
    !/^[A-Za-z0-9_-]{4,100}$/.test(settings.accountId) ||
    !/^[A-Za-z0-9_-]{4,100}$/.test(settings.hostId) ||
    typeof settings.ownerName !== "string" ||
    !settings.ownerName.trim() ||
    settings.ownerName.length > 120 ||
    typeof settings.model !== "string" ||
    !settings.model.trim()
  ) {
    throw Error("Configure the Zoom account ID, host user ID, owner name and OpenAI model.");
  }
  if (!Array.isArray(settings.routes) || !settings.routes.length)
    throw Error("Configure at least one authorized meeting route.");
  const titles = new Set();
  for (const route of settings.routes) {
    if (
      typeof route.title !== "string" ||
      !route.title.trim() ||
      route.title.length > 180 ||
      /[\r\n]/.test(route.title) ||
      titles.has(route.title) ||
      !/^[^\s,@<>]+@[^\s,@<>]+\.[^\s,@<>]+$/.test(route.recipient) ||
      !/^[1-9]\d{0,29}$/.test(route.listId) ||
      typeof route.calendarId !== "string" ||
      !/^[A-Za-z0-9_+=-]{1,500}$/.test(route.calendarId)
    )
      throw Error("Invalid or duplicate meeting route.");
    titles.add(route.title);
  }
  return {
    ...settings,
    now,
    from: new Date(now - 86_400_000).toISOString().slice(0, 10),
    to: new Date(now).toISOString().slice(0, 10),
  };
}

function zoomToken(body) {
  if (
    typeof body?.access_token !== "string" ||
    !/^[A-Za-z0-9_.~-]+$/.test(body.access_token) ||
    body.token_type?.toLowerCase() !== "bearer"
  )
    throw Error("Zoom OAuth did not return a valid access token.");
  return body.access_token;
}

function zoomPageToken(page) {
  const token = page?.next_page_token;
  if (typeof token !== "string" || token.length > 4096)
    throw Error("Zoom did not confirm the next-page token.");
  return token;
}

function zoomDownloadUrl(value, previous) {
  if (typeof value !== "string" || value.length > 4096)
    throw Error("Zoom returned an invalid recording address.");
  const zoomOrigin = /^https:\/\/((?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)*zoom\.us)(?=\/)/i;
  const origin = zoomOrigin.exec(value);
  const base = origin
    ? origin[0]
    : previous && value.startsWith("/")
      ? zoomOrigin.exec(previous)?.[0]
      : null;
  const path = origin ? value.slice(origin[0].length) : value;
  if (
    !base ||
    !/^\/{1,2}(?:rec\/(?:archive\/|meeting\/transcript\/)?download|recording\/download)\/[A-Za-z0-9_.~%+/=-]+(?:\?[A-Za-z0-9_.~%/+&=:-]+)?$/.test(
      path,
    ) ||
    /(?:^|\/)(?:\.|%2e){1,2}(?=\/|\?|$)/i.test(path) ||
    /%(?:2f|5c)/i.test(path.split("?")[0])
  ) {
    throw Error("Zoom returned an unapproved recording download address.");
  }
  return base + path;
}

function zoomRecordingPlans(pages, settings) {
  const results = new Map();
  if (!pages.length || zoomPageToken(pages.at(-1)))
    throw Error("The recording list is incomplete.");
  for (const page of pages) {
    if (!Array.isArray(page.meetings)) throw Error("Zoom returned an invalid recording list.");
    for (const record of page.meetings) {
      const route = settings.routes.find((candidate) => candidate.title === record?.topic);
      const began = Date.parse(record?.start_time);
      if (
        !route ||
        record.account_id !== settings.accountId ||
        record.host_id !== settings.hostId ||
        !["2", "8"].includes(String(record.type)) ||
        !Number.isFinite(began) ||
        began < settings.now - 86_400_000 ||
        began > settings.now
      )
        continue;
      if (typeof record.uuid !== "string" || !/^[A-Za-z0-9+/=_-]{1,160}$/.test(record.uuid)) {
        throw Error("Zoom did not identify the recorded meeting occurrence.");
      }
      const transcript = record.recording_files?.find(
        (file) =>
          file.file_type === "TRANSCRIPT" &&
          (!file.status || file.status === "completed") &&
          typeof file.download_url === "string",
      );
      if (!transcript) continue;
      if (Number(transcript.file_size) > 1_000_000)
        throw Error("A Zoom transcript exceeds the 1 MB processing limit.");
      const encoded = encodeURIComponent(record.uuid);
      const key = "zoom:" + settings.hostId + ":" + record.uuid;
      const candidate = {
        id: record.uuid,
        key,
        title: record.topic,
        began: new Date(began).toISOString(),
        route,
        downloadUrl: zoomDownloadUrl(transcript.download_url),
        uuidPath: record.uuid.includes("/") ? encodeURIComponent(encoded) : encoded,
        ownerName: settings.ownerName,
        model: settings.model,
      };
      if (results.has(key) && JSON.stringify(results.get(key)) !== JSON.stringify(candidate)) {
        throw Error("Zoom returned inconsistent references for the same meeting occurrence.");
      }
      results.set(key, candidate);
    }
  }
  if (results.size > 20) throw Error("There are more than 20 approved recordings in this run.");
  return [...results.values()];
}

function zoomTranscript(text) {
  if (
    typeof text !== "string" ||
    text.length > 100_000 ||
    !/^\uFEFF?WEBVTT(?:[ \t].*)?(?:\r?\n|$)/.test(text)
  ) {
    throw Error("Zoom did not return a supported WEBVTT transcript (up to 100,000 characters).");
  }
  const cues = [];
  for (const block of text
    .replace(/^\uFEFF/, "")
    .replace(/\r\n/g, "\n")
    .trim()
    .split(/\n[ \t]*\n/)
    .slice(1)) {
    const lines = block.split("\n");
    const time = lines.findIndex((line) => /^\d{2}:\d{2}(?::\d{2})?\.\d{3}\s+-->\s+/.test(line));
    if (time < 0 || time > 1) continue;
    const cue = lines
      .slice(time + 1)
      .map((line) => line.trim())
      .filter(Boolean)
      .join(" ");
    if (cue) cues.push(cue);
  }
  if (!cues.length || cues.length > 2000)
    throw Error("The Zoom recording has no supported transcript cues.");
  return cues;
}

function zoomMeetingEvidence(meeting, participantPages, transcript) {
  if (!participantPages.length || zoomPageToken(participantPages.at(-1)))
    throw Error("The participant list is incomplete.");
  const people = new Map();
  for (const page of participantPages) {
    if (!Array.isArray(page.participants))
      throw Error("Zoom returned an invalid participant list.");
    for (const person of page.participants) {
      if (typeof person.name !== "string" || !person.name.trim() || person.name.length > 180)
        continue;
      if (person.status === "in_waiting_room" || person.duration === 0) continue;
      const email =
        typeof person.user_email === "string" ? person.user_email.trim().toLowerCase() : "";
      people.set(email || person.name, { name: person.name.trim(), email });
    }
  }
  if (
    ![...people.values()].some((person) => person.email === meeting.route.recipient.toLowerCase())
  )
    return null;
  const cues = zoomTranscript(transcript);
  const { id, key, title, began, route, ownerName, model } = meeting;
  return {
    id,
    key,
    title,
    began,
    route,
    ownerName,
    model,
    participants: [...new Set([...people.values()].map((person) => person.name))],
    cues,
  };
}

export default async ({ settings, clientAuthorization }, context) => {
  const setup = zoomRunSettings(settings, Date.now());
  if (!/^Basic [A-Za-z0-9+/]+={0,2}$/.test(clientAuthorization))
    throw Error("Bind the Zoom OAuth Basic authorization secret.");
  const tokenUrl = new URL("https://zoom.us/oauth/token");
  tokenUrl.searchParams.set("grant_type", "account_credentials");
  tokenUrl.searchParams.set("account_id", setup.accountId);
  const grant = await context.fetch(tokenUrl, {
    method: "POST",
    headers: { authorization: clientAuthorization },
  });
  if (grant.status !== 200) throw Error("Zoom OAuth refused the application credentials.");
  const token = zoomToken(await grant.json());
  const headers = { authorization: "Bearer " + token };
  async function pages(path, params) {
    const url = new URL("https://api.zoom.us/v2" + path);
    for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
    url.searchParams.set("page_size", "100");
    const pages = [];
    const seen = new Set();
    do {
      const response = await context.fetch(url, { headers });
      if (response.status !== 200) throw Error("Zoom did not return the requested list.");
      const page = await response.json();
      pages.push(page);
      const next = zoomPageToken(page);
      if (!next) return pages;
      if (seen.has(next)) throw Error("Zoom repeated a pagination token.");
      seen.add(next);
      url.searchParams.set("next_page_token", next);
    } while (pages.length < 20);
    throw Error("Zoom returned more than 20 pages.");
  }
  const meetingPages = await pages("/users/" + encodeURIComponent(setup.hostId) + "/recordings", {
    from: setup.from,
    to: setup.to,
    recording_source_type: "cloud_recording_only",
  });
  const results = [];
  for (const meeting of zoomRecordingPlans(meetingPages, setup)) {
    if (await context.state.get(meeting.key)) {
      results.push({ id: meeting.id, status: "already_reserved" });
      continue;
    }
    try {
      const people = await pages("/past_meetings/" + meeting.uuidPath + "/participants", {});
      let response = await context.fetch(meeting.downloadUrl, { headers });
      if ([301, 302, 303, 307, 308].includes(response.status)) {
        const location = response.headers.get("location");
        if (!location) throw Error("Zoom omitted the recording redirection address.");
        response = await context.fetch(zoomDownloadUrl(location, meeting.downloadUrl), { headers });
      }
      if (response.status !== 200) throw Error("Zoom transcript download failed.");
      const evidence = zoomMeetingEvidence(meeting, people, await response.text());
      results.push(
        evidence
          ? { id: meeting.id, evidence }
          : { id: meeting.id, status: "approved_attendee_missing" },
      );
    } catch {
      results.push({ id: meeting.id, status: "zoom_read_failed" });
    }
  }
  return { meetings: results };
};

